<script setup lang="ts">
import{onMounted,reactive,ref}from'vue';import{agregarFoto,asignarPropietario,buscarPropietarios,eliminarFoto,establecerPrincipal,listarPredios,obtenerPredio,registrarPredio,type Option,type Payload,type Predio,type Propietario}from'../services/predios'
const rows=ref<Predio[]>([]),distritos=ref<Option[]>([]),sectores=ref<Option[]>([]),manzanas=ref<Option[]>([]),urbanizaciones=ref<Option[]>([]),calles=ref<Option[]>([]),centros=ref<Option[]>([]),loading=ref(false),saving=ref(false),modal=ref(false),detail=ref<Predio|null>(null),error=ref(''),success=ref(''),total=ref(0),lastPage=ref(1),ownerSearch=ref(''),owners=ref<Propietario[]>([]),photo=ref<File|null>(null);const filters=reactive({criterio:'',distrito_id:'',sector_id:'',manzana_id:'',urbanizacion_id:'',calle_id:'',con_cliente:'',page:1});const empty=():Payload=>({distrito_id:0,sector_id:0,manzana_id:0,lote:'',sublote:'',centro_poblado_id:0,urbanizacion_id:0,calle_id:0,direccion:'',referencia:'',observacion:''}),form=reactive<Payload>(empty())
async function load(page=1){loading.value=true;error.value='';filters.page=page;try{const r=await listarPredios(filters);rows.value=r.data;distritos.value=r.distritos;sectores.value=r.sectores;manzanas.value=r.manzanas;urbanizaciones.value=r.urbanizaciones;calles.value=r.calles;centros.value=r.centros_poblados;total.value=r.total;lastPage.value=r.last_page}catch(e){error.value=msg(e)}finally{loading.value=false}}function districtChanged(){filters.sector_id='';filters.manzana_id='';filters.urbanizacion_id='';filters.calle_id='';load(1)}function sectorChanged(){filters.manzana_id='';load(1)}function openCreate(){Object.assign(form,empty());modal.value=true;error.value=''}async function submit(){if(!form.distrito_id||!form.sector_id||!form.manzana_id||!form.lote||!form.calle_id||!form.direccion){error.value='Complete la ubicación catastral y la dirección obligatoria.';return}saving.value=true;error.value='';try{await registrarPredio({...form});success.value='Predio registrado correctamente.';modal.value=false;await load(1)}catch(e){error.value=msg(e)}finally{saving.value=false}}async function open(id:number){try{detail.value=await obtenerPredio(id);owners.value=[];ownerSearch.value=''}catch(e){error.value=msg(e)}}async function findOwners(){if(ownerSearch.value.length<3)return;try{owners.value=await buscarPropietarios(ownerSearch.value)}catch(e){error.value=msg(e)}}async function setOwner(x:Propietario){if(!detail.value)return;detail.value=await asignarPropietario(detail.value.id,x.id);success.value='Propietario asignado correctamente.';owners.value=[];await load(filters.page)}function pick(e:Event){photo.value=(e.target as HTMLInputElement).files?.[0]||null}async function upload(){if(!detail.value||!photo.value)return;const data=new FormData();data.append('fotografia',photo.value);try{await agregarFoto(detail.value.id,data);detail.value=await obtenerPredio(detail.value.id);photo.value=null;success.value='Fotografía agregada.'}catch(e){error.value=msg(e)}}async function principal(id:number){if(!detail.value)return;await establecerPrincipal(detail.value.id,id);detail.value=await obtenerPredio(detail.value.id);await load(filters.page)}async function removePhoto(id:number){if(!detail.value||!confirm('¿Eliminar esta fotografía?'))return;await eliminarFoto(detail.value.id,id);detail.value=await obtenerPredio(detail.value.id)}function msg(e:unknown){return e instanceof Error?e.message:'No se pudo completar la operación.'}onMounted(()=>load())
</script>
<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / EVAN / Catastro / Predios</nav><header class="hero"><div class="mark">P</div><div><small>EVAN · CATASTRO COMERCIAL</small><h1>Predios</h1><p>Ubicación catastral, propietarios, conexiones y registro fotográfico.</p></div><div class="counter"><b>{{total}}</b><span>predios encontrados</span></div><button @click="openCreate">+ Nuevo predio</button></header><p v-if="success" class="flash good">✓ {{success}}</p><p v-if="error" class="flash bad">{{error}}</p><section class="filters"><label>Buscar<input v-model.trim="filters.criterio" placeholder="Propietario, calle o urbanización" @keyup.enter="load(1)"></label><label>Distrito<select v-model="filters.distrito_id" @change="districtChanged"><option value="">Todos</option><option v-for="x in distritos" :key="x.id" :value="x.id">{{x.nombre}}</option></select></label><label>Sector<select v-model="filters.sector_id" @change="sectorChanged"><option value="">Todos</option><option v-for="x in sectores" :key="x.id" :value="x.id">{{x.nombre}}</option></select></label><label>Manzana<select v-model="filters.manzana_id"><option value="">Todas</option><option v-for="x in manzanas" :key="x.id" :value="x.id">{{x.nombre}}</option></select></label><label>Propietario<select v-model="filters.con_cliente"><option value="">Todos</option><option value="1">Con propietario</option><option value="0">Sin propietario</option></select></label><button @click="load(1)">Consultar</button></section><div v-if="loading" class="empty">Cargando predios…</div><div v-else-if="!rows.length" class="empty">No existen predios en la selección.</div><section v-else class="cards"><article v-for="x in rows" :key="x.id"><div class="photo"><img v-if="x.foto_principal" :src="x.foto_principal" alt="Predio"><span v-else>Sin fotografía</span><em>{{x.distrito}}</em></div><header><b>{{x.sector}} · Mz. {{x.manzana}} · Lt. {{x.lote}}{{x.sublote?`-${x.sublote}`:''}}</b></header><h2>{{x.propietario?.nombre||'Sin propietario asignado'}}</h2><p>{{x.urbanizacion}} · {{x.calle}} {{x.direccion}}</p><div class="tags"><span>{{x.conexiones.length}} conexión(es)</span><span>{{x.fotografias.length}} fotografía(s)</span></div><button @click="open(x.id)">Ver ficha del predio</button></article></section><footer v-if="lastPage>1" class="pages"><button :disabled="filters.page<=1" @click="load(filters.page-1)">Anterior</button><span>{{filters.page}} / {{lastPage}}</span><button :disabled="filters.page>=lastPage" @click="load(filters.page+1)">Siguiente</button></footer>
<div v-if="modal" class="backdrop" @mousedown.self="modal=false"><form class="modal" @submit.prevent="submit"><header><div><small>NUEVA UNIDAD CATASTRAL</small><h2>Registrar predio</h2></div><button type="button" @click="modal=false">×</button></header><fieldset><legend>Ubicación catastral</legend><div class="grid"><label>Distrito *<select v-model.number="form.distrito_id"><option :value="0">Seleccione</option><option v-for="x in distritos" :key="x.id" :value="x.id">{{x.nombre}}</option></select></label><label>Sector *<select v-model.number="form.sector_id"><option :value="0">Seleccione</option><option v-for="x in sectores" :key="x.id" :value="x.id">{{x.nombre}}</option></select></label><label>Manzana *<select v-model.number="form.manzana_id"><option :value="0">Seleccione</option><option v-for="x in manzanas" :key="x.id" :value="x.id">{{x.nombre}}</option></select></label><label>Lote *<input v-model.trim="form.lote"></label><label>Sublote<input v-model.trim="form.sublote"></label></div></fieldset><fieldset><legend>Dirección del predio</legend><div class="grid"><label>Centro poblado<select v-model.number="form.centro_poblado_id"><option :value="0">Seleccione</option><option v-for="x in centros" :key="x.id" :value="x.id">{{x.nombre}}</option></select></label><label>Urbanización<select v-model.number="form.urbanizacion_id"><option :value="0">Seleccione</option><option v-for="x in urbanizaciones" :key="x.id" :value="x.id">{{x.nombre}}</option></select></label><label>Calle *<select v-model.number="form.calle_id"><option :value="0">Seleccione</option><option v-for="x in calles" :key="x.id" :value="x.id">{{x.nombre}}</option></select></label><label class="span2">Complemento de dirección *<input v-model.trim="form.direccion"></label><label>Referencia<input v-model.trim="form.referencia"></label></div><label>Observaciones<textarea v-model.trim="form.observacion" rows="2"></textarea></label></fieldset><footer><button type="button" class="clear" @click="modal=false">Cancelar</button><button :disabled="saving">{{saving?'Registrando…':'Registrar predio'}}</button></footer></form></div>
<div v-if="detail" class="backdrop" @mousedown.self="detail=null"><section class="modal detail"><header><div><small>PREDIO N.° {{detail.id}}</small><h2>{{detail.distrito}} · {{detail.sector}} · Mz. {{detail.manzana}} · Lt. {{detail.lote}}</h2><p>{{detail.urbanizacion}} · {{detail.calle}} {{detail.direccion}}</p></div><button @click="detail=null">×</button></header><section class="owner"><div v-if="detail.propietario"><span>PROPIETARIO</span><b>{{detail.propietario.nombre}}</b><small>{{detail.propietario.documento_tipo}} {{detail.propietario.documento}}</small></div><div v-else><span>SIN PROPIETARIO</span><div class="owner-search"><input v-model.trim="ownerSearch" placeholder="Nombre o documento" @keyup.enter="findOwners"><button @click="findOwners">Buscar</button></div><button v-for="x in owners" :key="x.id" class="owner-result" @click="setOwner(x)">{{x.nombre}} · {{x.documento}}</button></div></section><h3>Fotografías</h3><div class="gallery"><article v-for="x in detail.fotografias" :key="x.id" :class="{main:x.principal}"><img :src="x.url" alt="Fotografía"><footer><button v-if="!x.principal" @click="principal(x.id)">Principal</button><button class="remove" @click="removePhoto(x.id)">Eliminar</button></footer></article></div><div class="upload"><input type="file" accept="image/*" capture="environment" @change="pick"><button :disabled="!photo" @click="upload">Agregar fotografía</button></div><h3>Conexiones</h3><div v-if="!detail.conexiones.length" class="empty small">El predio no tiene conexiones asociadas.</div><div class="connections"><article v-for="x in detail.conexiones" :key="x.id"><header><b>{{x.codigo}} · SICI {{x.sici}}</b><em>{{x.estado}}</em></header><span>{{x.categoria}} · {{x.situacion}}</span><div><i v-for="s in x.servicios" :key="s">{{s}}</i></div></article></div><footer><button class="clear" @click="detail=null">Cerrar</button></footer></section></div></div></template>
